window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[250]={"id":"250","numero":250,"titre":"Dénutrition","objectifs":[{"id":"250-1","rang":"B","rubrique":"Epidémiologie","titre":"Connaître l'épidémiologie de la dénutrition","contenu":"<p>La <span class=\"kw-def\">dénutrition</span> touche <strong>tous les âges</strong>. Elle peut accompagner toute <span class=\"kw-etio\">pathologie</span> aiguë ou chronique, organique ou psychiatrique, ainsi que les situations de <span class=\"kw-etio\">précarité socio-économique</span>.</p>\n      <p><strong>Prévalence à l'hôpital :</strong></p>\n      <ul>\n        <li><span class=\"kw-chiffre\">10 %</span> des enfants</li>\n        <li><span class=\"kw-chiffre\">30 %</span> des adultes</li>\n        <li><span class=\"kw-chiffre\">50 %</span> des sujets âgés (<span class=\"kw-chiffre\">&gt; 70 ans</span>)</li>\n      </ul>\n      <p><strong>Prévalence hors hôpital :</strong></p>\n      <ul>\n        <li><span class=\"kw-chiffre\">4 %</span> des Français de <span class=\"kw-chiffre\">70-79 ans</span> vivant à domicile</li>\n        <li><span class=\"kw-chiffre\">10 %</span> après <span class=\"kw-chiffre\">80 ans</span></li>\n      </ul>\n      <p>La prévalence globale en France concerne près de <span class=\"kw-chiffre\">3 millions</span> d'individus.</p>","frequence":0},{"id":"250-2","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les facteurs de risque de la dénutrition chez l'adulte","contenu":"<p>En dénutrition, on parle de <strong>situations à risque</strong> plutôt que de facteurs de risque. Toute <span class=\"kw-etio\">pathologie</span> sévère ou chronique dans laquelle les apports ne couvrent pas les besoins nutritionnels expose au risque.</p>\n      <p>Le <strong>déficit énergétique</strong> apparaît lorsque les <em>entrées</em> deviennent chroniquement inférieures aux <em>sorties</em>.</p>\n      <table>\n        <thead><tr><th>Mécanisme</th><th>Situations</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>↓ Entrées</strong></td>\n            <td>\n              <ul>\n                <li><strong>Baisse des ingesta</strong> (de très loin la situation la plus fréquente)</li>\n                <li><span class=\"kw-clinique\">Malabsorption digestive</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>↑ Sorties</strong></td>\n            <td>\n              <ul>\n                <li>Augmentation des <span class=\"kw-def\">dépenses énergétiques</span> totales journalières (rare)</li>\n                <li>Pertes de substrats énergétiques : <span class=\"kw-clinique\">pertes digestives</span> (entéropathies exsudatives), <span class=\"kw-clinique\">pertes urinaires</span> (glycosurie, syndrome néphrotique), <span class=\"kw-clinique\">pertes cutanées</span> (lésions étendues, <span class=\"kw-alerte\">brûlures</span>)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>","frequence":0},{"id":"250-3","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les facteurs de risque de la dénutrition chez l'enfant","contenu":"<p>Les situations à risque chez l'<strong>enfant</strong> sont <strong>les mêmes que chez l'adulte</strong> (LiSA) : toute pathologie aiguë ou chronique conduisant à des apports insuffisants, malabsorption, ou pertes de substrats énergétiques.</p>\n      <p class=\"obj-renvois\"><em>📎 Item lié : 250-2 — Facteurs de risque chez l'adulte</em></p>","frequence":0},{"id":"250-4","rang":"A","rubrique":"Pronostic","titre":"Connaître les conséquences de la dénutrition","contenu":"<p>La <span class=\"kw-def\">dénutrition</span> a des conséquences <strong>multi-systémiques</strong> qui aggravent le pronostic de toute pathologie associée.</p>\n      <table>\n        <thead><tr><th>Système</th><th>Conséquences</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Musculaire</strong></td><td><span class=\"kw-clinique\">Sarcopénie</span>, fonte musculaire, ↓ force, chutes, perte d'autonomie</td></tr>\n          <tr><td><strong>Immunitaire</strong></td><td>↑ risque d'<span class=\"kw-alerte\">infections</span> (nosocomiales, opportunistes), retard de <span class=\"kw-clinique\">cicatrisation</span></td></tr>\n          <tr><td><strong>Cutané</strong></td><td><span class=\"kw-alerte\">Escarres</span>, retard de cicatrisation post-opératoire</td></tr>\n          <tr><td><strong>Digestif</strong></td><td>Atrophie villositaire, <span class=\"kw-clinique\">malabsorption</span> secondaire</td></tr>\n          <tr><td><strong>Cardio-respiratoire</strong></td><td>↓ masse myocardique, fatigabilité des muscles respiratoires</td></tr>\n          <tr><td><strong>Psychique</strong></td><td>Apathie, <span class=\"kw-clinique\">syndrome dépressif</span>, troubles cognitifs</td></tr>\n          <tr><td><strong>Pronostic global</strong></td><td>↑ durée de séjour hospitalier, ↑ complications post-opératoires, ↑ <span class=\"kw-alerte\">mortalité</span></td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"250-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les critères diagnostiques de la dénutrition chez l'enfant","contenu":"<p>Chez l'enfant, en croissance, on utilise les <strong>courbes staturo-pondérales et de corpulence</strong> (<span class=\"kw-def\">IMC</span>) définies par l'<span class=\"kw-def\">IOTF</span> (International Obesity Task Force) selon sexe et âge (carnet de santé).</p>\n      <p><strong>Le diagnostic associe au moins 1 critère phénotypique + 1 critère étiologique.</strong></p>\n      <p><strong>Critères phénotypiques (&lt; 18 ans, 1 seul suffit) :</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">Perte de poids</span> <span class=\"kw-chiffre\">≥ 5 %</span> en <span class=\"kw-chiffre\">1 mois</span></li>\n        <li>Perte de poids <span class=\"kw-chiffre\">≥ 10 %</span> en <span class=\"kw-chiffre\">6 mois</span></li>\n        <li>Perte de poids <span class=\"kw-chiffre\">≥ 10 %</span> par rapport au poids habituel avant maladie</li>\n        <li><span class=\"kw-bio\">IMC</span> <span class=\"kw-chiffre\">&lt; courbe IOTF 18,5</span></li>\n        <li><span class=\"kw-clinique\">Stagnation pondérale</span> aboutissant à un poids situé <strong>2 couloirs en dessous</strong> du couloir habituel</li>\n      </ul>\n      <p><strong>Critères étiologiques (1 seul suffit) :</strong></p>\n      <ul>\n        <li>Réduction de la prise alimentaire <span class=\"kw-chiffre\">≥ 50 %</span> pendant <span class=\"kw-chiffre\">&gt; 1 semaine</span>, ou toute réduction des apports pendant <span class=\"kw-chiffre\">&gt; 2 semaines</span></li>\n        <li>Absorption réduite (maldigestion/malabsorption)</li>\n        <li>Situation d'agression (hypercatabolisme protéique ± inflammation) : pathologie aiguë, chronique évolutive ou maligne évolutive</li>\n      </ul>\n      <p><strong>Sévérité :</strong></p>\n      <table>\n        <thead><tr><th>Dénutrition modérée</th><th>Dénutrition sévère</th></tr></thead>\n        <tbody>\n          <tr><td>Perte poids <span class=\"kw-chiffre\">≥ 5 % et ≤ 10 %</span> / 1 mois</td><td>Perte poids <span class=\"kw-chiffre\">&gt; 10 %</span> / 1 mois</td></tr>\n          <tr><td>Perte poids <span class=\"kw-chiffre\">≥ 10 % et ≤ 15 %</span> / 6 mois</td><td>Perte poids <span class=\"kw-chiffre\">&gt; 15 %</span> / 6 mois</td></tr>\n          <tr><td>Courbe <span class=\"kw-chiffre\">IOTF 17 &lt; IMC &lt; IOTF 18,5</span></td><td><span class=\"kw-bio\">IMC ≤ courbe IOTF 17</span></td></tr>\n          <tr><td>Stagnation entre <span class=\"kw-chiffre\">2 et 3 couloirs</span> en dessous</td><td>Stagnation <span class=\"kw-chiffre\">≥ 3 couloirs</span> en dessous</td></tr>\n          <tr><td>—</td><td><span class=\"kw-alerte\">Infléchissement statural</span> (perte ≥ 1 couloir sur la taille)</td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"250-6","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les critères diagnostiques de la dénutrition chez l'adulte (< 70 ans)","contenu":"<p>Recommandations <span class=\"kw-def\">HAS 2019</span>. Le diagnostic associe <strong>au moins 1 critère phénotypique + 1 critère étiologique</strong>.</p>\n      <p><strong>Critères phénotypiques (adulte &lt; 70 ans, 1 seul suffit) :</strong></p>\n      <ul>\n        <li><span class=\"kw-clinique\">Perte de poids</span> <span class=\"kw-chiffre\">≥ 5 %</span> en <span class=\"kw-chiffre\">1 mois</span></li>\n        <li>Perte de poids <span class=\"kw-chiffre\">≥ 10 %</span> en <span class=\"kw-chiffre\">6 mois</span></li>\n        <li>Perte de poids <span class=\"kw-chiffre\">≥ 10 %</span> par rapport au poids habituel avant maladie</li>\n        <li><span class=\"kw-bio\">IMC &lt; 18,5</span></li>\n        <li>Réduction quantifiée de la <span class=\"kw-clinique\">masse musculaire</span> et/ou de la <span class=\"kw-clinique\">fonction musculaire</span></li>\n      </ul>\n      <p><strong>Critères étiologiques (1 seul suffit) :</strong></p>\n      <ul>\n        <li>Réduction de la prise alimentaire <span class=\"kw-chiffre\">≥ 50 %</span> pendant <span class=\"kw-chiffre\">&gt; 1 semaine</span>, ou toute réduction pendant <span class=\"kw-chiffre\">&gt; 2 semaines</span></li>\n        <li>Absorption réduite (maldigestion/malabsorption)</li>\n        <li>Situation d'agression (hypercatabolisme protéique ± inflammation)</li>\n      </ul>\n      <p><strong>Sévérité :</strong></p>\n      <table>\n        <thead><tr><th>Dénutrition modérée</th><th>Dénutrition sévère</th></tr></thead>\n        <tbody>\n          <tr><td>Perte <span class=\"kw-chiffre\">≥ 5 %</span> / 1 mois</td><td>Perte <span class=\"kw-chiffre\">&gt; 10 %</span> / 1 mois</td></tr>\n          <tr><td>Perte <span class=\"kw-chiffre\">≥ 10 %</span> / 6 mois</td><td>Perte <span class=\"kw-chiffre\">&gt; 15 %</span> / 6 mois</td></tr>\n          <tr><td>Perte <span class=\"kw-chiffre\">≥ 10 %</span> vs poids habituel avant maladie</td><td>Perte <span class=\"kw-chiffre\">≥ 15 %</span> vs poids habituel avant maladie</td></tr>\n          <tr><td><span class=\"kw-chiffre\">17 &lt; IMC &lt; 18,5</span></td><td><span class=\"kw-bio\">IMC ≤ 17</span></td></tr>\n          <tr><td><span class=\"kw-bio\">Albuminémie &gt; 30 et &lt; 35 g/L</span></td><td><span class=\"kw-alerte\">Albuminémie &lt; 30 g/L</span></td></tr>\n        </tbody>\n      </table>","frequence":3},{"id":"250-7","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les critères diagnostiques de la dénutrition chez la personne âgée (> 70 ans)","contenu":"<p>Critères révisés <span class=\"kw-def\">HAS 2021</span>. Comme chez l'adulte, il faut <strong>1 critère phénotypique + 1 critère étiologique</strong>. Le dosage de l'<span class=\"kw-bio\">albuminémie</span> seule ne permet <strong>pas</strong> de porter le diagnostic.</p>\n      <p><strong>Critères phénotypiques :</strong></p>\n      <table>\n        <thead><tr><th>Paramètre</th><th>Dénutrition</th><th>Dénutrition sévère</th></tr></thead>\n        <tbody>\n          <tr><td>Perte de poids en 1 mois</td><td><span class=\"kw-chiffre\">≥ 5 % et &lt; 10 %</span></td><td><span class=\"kw-chiffre\">≥ 10 %</span></td></tr>\n          <tr><td>Perte de poids en 6 mois</td><td><span class=\"kw-chiffre\">≥ 10 % et &lt; 15 %</span></td><td><span class=\"kw-chiffre\">≥ 15 %</span></td></tr>\n          <tr><td>Perte vs poids habituel</td><td><span class=\"kw-chiffre\">≥ 10 % et &lt; 15 %</span></td><td><span class=\"kw-chiffre\">≥ 15 %</span></td></tr>\n          <tr><td><span class=\"kw-bio\">IMC</span> (kg/m²)</td><td><span class=\"kw-chiffre\">&lt; 22</span></td><td><span class=\"kw-chiffre\">&lt; 20</span></td></tr>\n          <tr><td><span class=\"kw-clinique\">Sarcopénie</span> (réduction confirmée de la force ET de la masse musculaires)</td><td>+</td><td>+</td></tr>\n        </tbody>\n      </table>\n      <p><strong>Un seul paramètre altéré suffit</strong> pour porter le diagnostic.</p>\n      <div class=\"callout callout-info\"><strong>Rôle de l'albuminémie chez le &gt; 70 ans :</strong> <span class=\"kw-bio\">30-35 g/L</span> = argument pour dénutrition modérée ; <span class=\"kw-alerte\">&lt; 30 g/L</span> = critère de dénutrition sévère.</div>\n      <p><strong>Critères étiologiques (1 seul suffit) :</strong> identiques à l'adulte &lt; 70 ans (réduction ingesta ≥ 50 % / 1 semaine, malabsorption, situation d'agression).</p>","frequence":1},{"id":"250-8","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les examens complémentaires permettant de qualifier une dénutrition","contenu":"<p>Les examens biologiques gardent leur utilité pour la <strong>recherche de complications</strong> et la <strong>sévérité</strong>. Le diagnostic reste avant tout <strong>clinique</strong> (critères phénotypiques + étiologiques).</p>\n      <table>\n        <thead><tr><th>Examen</th><th>Intérêt</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-bio\">Albuminémie</span></strong></td><td>Critère de sévérité (interprété avec la <span class=\"kw-bio\">CRP</span> — protéine négative de l'inflammation)</td></tr>\n          <tr><td><strong><span class=\"kw-bio\">CRP</span></strong></td><td>Contexte inflammatoire : abaisse l'albuminémie indépendamment de l'état nutritionnel</td></tr>\n          <tr><td><strong>Évaluation musculaire</strong></td><td>Force (dynamométrie/hand-grip), masse musculaire (impédancemétrie, DEXA, mesures anthropométriques) — reco HAS 2019</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège.</strong> L'albuminémie seule <strong>ne diagnostique pas</strong> la dénutrition (surtout chez le sujet âgé) : elle sert uniquement à en <strong>grader la sévérité</strong>.</div>","frequence":0},{"id":"250-9","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes de la complémentation orale, de la nutrition entérale et parentérale","contenu":"<p>La PEC suit l'<strong>arbre décisionnel <span class=\"kw-def\">SFNCM</span></strong> et dépend de : (1) sévérité de la dénutrition, (2) importance de la réduction des ingesta, (3) fonctionnalité du tube digestif, (4) troubles de la conscience/déglutition. <strong>Traiter la cause</strong> si possible.</p>\n      <h4>Alimentation orale et CNO</h4>\n      <ul>\n        <li><strong>Adapter la texture</strong> (petits morceaux, hachée, mixée) si troubles bucco-dentaires ou de la <span class=\"kw-clinique\">déglutition</span></li>\n        <li>Tenir compte des goûts et aversions</li>\n        <li><strong>Enrichir</strong> l'alimentation en matières grasses, glucides, protéines</li>\n        <li><strong>Fractionner</strong> — collations entre les repas ; <span class=\"kw-ttt\">CNO</span> à distance des repas et le soir pour réduire le jeûne nocturne</li>\n        <li>CNO : ≤ <span class=\"kw-chiffre\">2 unités/jour</span>, à distance des repas, arômes/textures variés</li>\n      </ul>\n      <div class=\"callout callout-info\">Les <strong>CNO n'ont pas vocation à se substituer</strong> aux repas mais à les compléter.</div>\n      <h4>Nutrition entérale</h4>\n      <p>Administration directe dans le tube digestif (estomac ou intestin grêle) via <span class=\"kw-ttt\">sonde</span> ou <span class=\"kw-ttt\">stomie</span>, d'un mélange nutritif <strong>complet</strong> (protéines, glucides, lipides, minéraux, vitamines, oligo-éléments) <strong>dépourvu de gluten</strong>.</p>\n      <p>Le site <strong>gastrique</strong> est privilégié. Le site <strong>jéjunal</strong> est réservé aux contre-indications, impossibilités ou échecs de l'abord gastrique : <span class=\"kw-ci\">RGO réfractaire</span> avec risque d'inhalation, <span class=\"kw-ci\">gastrectomie</span> partielle étendue ou totale, <span class=\"kw-ci\">cancer de l'estomac</span>, <span class=\"kw-ci\">sténose duodénale</span>.</p>\n      <h4>Nutrition parentérale</h4>\n      <p>Perfusion IV d'un mélange nutritif via une voie veineuse (habituellement <strong>centrale</strong>). Poches compartimentées, reconstituables extemporanément, contenant acides aminés + glucose + lipides ± électrolytes, <strong>mais sans micronutriments</strong>.</p>\n      <div class=\"callout callout-warn\"><strong>Prescrire systématiquement chaque jour</strong> un mélange de <span class=\"kw-ttt\">poly-vitamines</span> et un mélange d'<span class=\"kw-ttt\">oligo-éléments</span>.</div>","frequence":1},{"id":"250-10","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic et de la prévention du syndrome de renutrition","contenu":"<p>Le <span class=\"kw-def\">syndrome de renutrition inappropriée</span> (<span class=\"kw-def\">SRI</span>) est une <strong><span class=\"kw-alerte\">complication métabolique potentiellement mortelle</span></strong> qui peut survenir lors de la réintroduction des apports nutritionnels chez un patient dénutri, <strong>quelle que soit la modalité</strong> (orale, entérale ou parentérale).</p>\n      <p>Il apparaît généralement dans les <span class=\"kw-chiffre\">72 heures</span> suivant le début de la renutrition.</p>\n      <h4>Diagnostic biologique</h4>\n      <ul>\n        <li><strong><span class=\"kw-alerte\">Hypophosphorémie</span></strong> (élément central)</li>\n        <li>± Déficits associés : <span class=\"kw-bio\">hypokaliémie</span>, <span class=\"kw-bio\">hypomagnésémie</span>, carence en <span class=\"kw-ttt\">thiamine (vitamine B1)</span></li>\n      </ul>\n      <h4>Signes cliniques</h4>\n      <p>Souvent asymptomatique. Quand présents, polymorphes :</p>\n      <ul>\n        <li><strong>Cardiaques :</strong> <span class=\"kw-alerte\">arythmie</span>, <span class=\"kw-clinique\">syncope</span>, <span class=\"kw-alerte\">insuffisance cardiaque aiguë</span></li>\n        <li><strong>Neuro-musculaires :</strong> paresthésies, fasciculations, tétanie, paralysies, confusion, <span class=\"kw-clinique\">encéphalopathie</span>, <span class=\"kw-alerte\">convulsions</span>, fatigue et douleurs musculaires, <span class=\"kw-alerte\">rhabdomyolyse</span></li>\n      </ul>\n      <h4>Prévention</h4>\n      <ul>\n        <li><strong>Correction et supplémentation systématique en <span class=\"kw-ttt\">phosphore</span></strong></li>\n        <li>Correction des déficits associés : <span class=\"kw-ttt\">potassium</span>, <span class=\"kw-ttt\">magnésium</span>, <span class=\"kw-ttt\">vitamine B1</span></li>\n        <li><strong>Début progressif</strong> de la renutrition</li>\n      </ul>\n      <h4>Surveillance</h4>\n      <p>Surveillance de la <span class=\"kw-bio\">phosphorémie</span> et de la <span class=\"kw-bio\">kaliémie</span> <strong>avant et durant les premiers jours</strong> de la renutrition.</p>","frequence":1}],"astuces":[],"liensGlobaux":[{"href":"https://www.has-sante.fr/upload/docs/application/pdf/2019-11/reco277_recommandations_rbp_denutrition_cd_2019_11_13_v0.pdf","label":"has-sante.fr"},{"href":"https://www.pedia-univ.fr/deuxieme-cycle/referentiel/gastroenterologie-nutrition-chirurgie-abdomino-pelvienne/denutrition","label":"pedia-univ.fr"},{"href":"https://fr.wikipedia.org/wiki/Kwashiorkor","label":"fr.wikipedia.org"},{"href":"https://www.sefi-nutrition.com/utiliser-sefi","label":"sefi-nutrition.com"},{"href":"https://www.mna-elderly.com/sites/default/files/2021-10/MNA-french.pdf","label":"mna-elderly.com"},{"href":"https://www.ffamco-ehpad.org/docs/2015/ppt_3e_journee_annuelle_ffamco/7-rosati_simon.pdf","label":"ffamco-ehpad.org"},{"href":"https://www.hug.ch/vdoc/HUG_000000843.pdf","label":"hug.ch"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Patient dénutri ou à risque nutritionnel — Évaluer : état nutritionnel, besoins protéino-énergétiques, ingesta vs besoins","detail":"<h4>CAT — Support nutritionnel de la dénutrition — Choix de la voie d'apport selon la couverture des besoins, la fonctionnalité du tube digestif et la durée prévisible</h4>","branches":[{"to":"q-besoins","label":"Bilan nutritionnel","color":"blue"}]},{"id":"q-besoins","kind":"decision","label":"Les ingesta couvrent-ils les besoins ET EVA-SEFI ≥ 7/10 ?","branches":[{"to":"t-surveillance","label":"Oui","color":"green"},{"to":"q-tube","label":"Non — support requis","color":"amber"}]},{"id":"t-surveillance","kind":"terminal","label":"Pas de support — surveillance simple","color":"green","detail":"<h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-clinique\">Poids</span> <span class=\"kw-chiffre\">1×/semaine</span></li><li>Si ingesta &lt; <span class=\"kw-chiffre\">2/3 des besoins</span> ou EVA &lt; <span class=\"kw-chiffre\">7/10</span> → <span class=\"kw-ttt\">alimentation enrichie + CNO</span> et <span class=\"kw-def\">réévaluation</span> hebdomadaire</li></ul>"},{"id":"q-tube","kind":"decision","label":"Tube digestif fonctionnel ? — Et pas d'échec d'une nutrition entérale bien conduite","branches":[{"to":"q-orale","label":"Oui (tube fonctionnel)","color":"green"},{"to":"q-duree-par","label":"Non, ou échec de la nutrition entérale","color":"red"}]},{"id":"q-orale","kind":"decision","label":"Alimentation orale possible et ≥ 2/3 des besoins ?","branches":[{"to":"t-orale","label":"Oui (mange raisonnablement)","color":"amber"},{"to":"q-duree-ent","label":"Non (ingesta < 2/3 ou EVA < 7/10 malgré CNO)","color":"amber"}]},{"id":"t-orale","kind":"terminal","label":"Enrichissement alimentaire + CNO","color":"amber","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Enrichir l'alimentation</span> sans augmenter le volume + <span class=\"kw-ttt\">CNO</span> <span class=\"kw-bio\">hyperénergétiques/hyperprotidiques</span></li><li>CNO ≤ <span class=\"kw-chiffre\">2×/j</span> en dehors des repas — objectif <span class=\"kw-chiffre\">+400 kcal/j</span> et <span class=\"kw-chiffre\">+30 g de protéines/j</span></li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-clinique\">Réévaluation hebdomadaire</span> ; escalade vers la nutrition entérale si insuffisant</li></ul>"},{"id":"q-duree-ent","kind":"decision","label":"Durée prévisible de la nutrition entérale ?","branches":[{"to":"t-sng","label":"< 4 semaines","color":"amber"},{"to":"t-gastro","label":"> 4-6 semaines","color":"amber"}]},{"id":"t-sng","kind":"terminal","label":"Nutrition entérale par SNG","color":"amber","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Sonde nasogastrique</span> radio-opaque ; <span class=\"kw-imagerie\">RX</span> de contrôle obligatoire après la pose</li><li>Débit <span class=\"kw-chiffre\">80-120 mL/h</span> ; administration en <span class=\"kw-ttt\">proclive 30°</span> (prévention de la <span class=\"kw-alerte\">pneumopathie d'inhalation</span>)</li></ul><h4>Délai</h4><ul><li>Indiquée si durée prévisible <span class=\"kw-chiffre\">&lt; 4 semaines</span></li></ul>"},{"id":"t-gastro","kind":"terminal","label":"Gastrostomie / jéjunostomie","color":"amber","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Gastrostomie</span> (voie endoscopique ou radiologique) ou <span class=\"kw-ttt\">jéjunostomie</span> (chirurgicale)</li><li>Précautions : <span class=\"kw-ci\">arrêt des anticoagulants</span>, <span class=\"kw-ttt\">antibioprophylaxie</span>, asepsie chirurgicale</li></ul><h4>Délai</h4><ul><li>Indiquée si durée prévisible <span class=\"kw-chiffre\">&gt; 4-6 semaines</span></li></ul>"},{"id":"q-duree-par","kind":"decision","label":"Durée prévisible de la nutrition parentérale ?","branches":[{"to":"t-vvp","label":"Courte (≤ 10 jours)","color":"red"},{"to":"t-vvc","label":"Prolongée (> 1 mois)","color":"red"}]},{"id":"t-vvp","kind":"terminal","label":"Nutrition parentérale sur VVP (courte durée)","color":"red","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Voie veineuse périphérique</span> sur veine du bras ; solutés <span class=\"kw-bio\">hyperosmolaires</span> spécifiques (≤ <span class=\"kw-chiffre\">1000 kcal/j</span>)</li></ul><h4>Délai</h4><ul><li>Réservée à la <span class=\"kw-chiffre\">courte durée (≤ 10 jours)</span> et aux besoins réduits</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Prévenir le <span class=\"kw-alerte\">SRI</span> : montée calorique <span class=\"kw-ttt\">progressive</span> + <span class=\"kw-ttt\">phosphore</span> et <span class=\"kw-ttt\">vitamine B1</span></li></ul>"},{"id":"t-vvc","kind":"terminal","label":"Nutrition parentérale sur VVC / PICC (prolongée)","color":"red","detail":"<h4>Conduite</h4><ul><li>Indiquée si <span class=\"kw-ci\">tube digestif non fonctionnel</span> ou <span class=\"kw-ci\">échec de la nutrition entérale</span></li><li><span class=\"kw-ttt\">VVC</span> dans le système cave supérieur si <span class=\"kw-chiffre\">&gt; 1 mois</span> ; <span class=\"kw-ttt\">PICC</span> limité à <span class=\"kw-chiffre\">6 mois</span></li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>Risque de <span class=\"kw-alerte\">SRI</span> majeur : <span class=\"kw-bio\">phosphorémie</span> avant et pendant la renutrition, apports caloriques <span class=\"kw-ttt\">progressifs</span></li></ul>"}]},"cards":[{"i":"5266142cce2a","n":250,"o":"250-4","u":"Pronostic","t":"Connaître les conséquences de la dénutrition","q":"Quelles sont les complications cardiovasculaires de la dénutrition ?","a":"<p>Les complications cardiovasculaires de la dénutrition incluent :</p><ul><li>Diminution de la masse cardiaque (<strong>amyotrophie</strong> myocardique).</li><li>Bradycardie.</li><li>Hypotension artérielle.</li><li>Insuffisance cardiaque.</li><li>Troubles du rythme cardiaque.</li></ul>"},{"i":"6cc502a77813","n":250,"o":"250-4","u":"Pronostic","t":"Connaître les conséquences de la dénutrition","q":"Quelles sont les répercussions neurologiques et psychologiques de la dénutrition ?","a":"<p>Les conséquences neurologiques et psychologiques de la dénutrition sont :</p><ul><li><strong>Asthénie</strong>.</li><li>Troubles de la concentration.</li><li>Altération des fonctions cognitives.</li><li><strong>Dépression</strong>, irritabilité, apathie.</li><li>Neuropathies périphériques.</li></ul>"},{"i":"7b27fd7b81ac","n":250,"o":"250-4","u":"Pronostic","t":"Connaître les conséquences de la dénutrition","q":"Quelles sont les conséquences hématologiques et ostéoarticulaires de la dénutrition ?","a":"<p>La dénutrition peut provoquer :</p><ul><li><strong>Anémie</strong> (souvent multifactorielle).</li><li>Leucopénie, lymphopénie.</li><li><strong>Ostéopénie/ostéoporose</strong> avec majoration du risque de fracture.</li><li>Amyotrophie et sarcopénie (diminution de la masse musculaire).</li></ul>"},{"i":"aaf27bec5f3b","n":250,"o":"250-4","u":"Pronostic","t":"Connaître les conséquences de la dénutrition","q":"Quelles sont les conséquences immunologiques et infectieuses de la dénutrition ?","a":"<p>La dénutrition entraîne :</p><ul><li>Une <strong>immunodépression</strong> (diminution des défenses immunitaires).</li><li>Une augmentation de la fréquence et de la gravité des <strong>infections</strong>.</li><li>Une altération de la cicatrisation.</li></ul>"},{"i":"c05f77eb4e6b","n":250,"o":"250-4","u":"Pronostic","t":"Connaître les conséquences de la dénutrition","q":"Quelles sont les conséquences respiratoires, rénales et digestives de la dénutrition ?","a":"<p>La dénutrition peut entraîner :</p><ul><li><strong>Insuffisance respiratoire</strong> (faiblesse des muscles respiratoires).</li><li>Insuffisance rénale fonctionnelle.</li><li><strong>Atrophie de la muqueuse intestinale</strong> occasionnant des troubles de l'absorption.</li><li>Diarrhée.</li></ul>"},{"i":"043bc03b79ca","n":250,"o":"250-5","u":"Diagnostic positif","t":"Connaître les critères diagnostiques de la dénutrition chez l'enfant","q":"Quels sont les critères phénotypiques de la dénutrition chez l'enfant et comment sont-ils classés ?","a":"<p>Les critères phénotypiques de la dénutrition chez l'enfant sont classés selon l'âge :</p><ul><li>Pour les <strong>0-2 ans</strong> : un <strong>poids/âge &lt; -3 DS</strong> ou une <strong>perte de poids &gt; 10%</strong> par rapport au poids habituel.</li><li>Pour les <strong>2-18 ans</strong> : un <strong>IMC/âge &lt; -2 DS</strong> (ou &lt; -3 DS pour les dénutritions sévères) ou une <strong>perte de poids &gt; 10%</strong> par rapport au poids habituel en 3 mois ou <strong>&gt; 5%</strong> en 1 mois.</li></ul>"},{"i":"7b3ecb814657","n":250,"o":"250-5","u":"Diagnostic positif","t":"Connaître les critères diagnostiques de la dénutrition chez l'enfant","q":"Actuellement, selon la HAS, quels sont les deux principaux groupes de critères diagnostiques pour la dénutrition de l'enfant ?","a":"<p>Actuellement, selon la HAS, le diagnostic de dénutrition chez l'enfant repose sur l'identification d'au moins un <strong>critère phénotypique</strong> et d'au moins un <strong>critère étiologique</strong>.</p>"},{"i":"ce879ec97d23","n":250,"o":"250-5","u":"Diagnostic positif","t":"Connaître les critères diagnostiques de la dénutrition chez l'enfant","q":"Quels sont les critères étiologiques à prendre en compte pour le diagnostic de dénutrition chez l'enfant ?","a":"<p>Les critères étiologiques de la dénutrition chez l'enfant incluent :</p><ul><li>Un <strong>apport alimentaire insuffisant</strong> (oral, entéral, parentéral).</li><li>Une <strong>malabsorption</strong> des nutriments (ex: mucoviscidose, maladies inflammatoires chroniques de l'intestin).</li><li>Une <strong>augmentation des besoins métaboliques</strong> (ex: maladies chroniques, infections graves, brûlures étendues).</li><li>Une <strong>perte excessive de nutriments</strong> (ex: fistules digestives, néphropathies avec fuite protéique).</li></ul>"},{"i":"01ad87cb289a","n":250,"o":"250-6","u":"Diagnostic positif","t":"Connaître les critères diagnostiques de la dénutrition chez l'adulte (< 70 ans)","q":"Quels sont les critères phénotypiques à considérer pour le diagnostic de dénutrition chez l'adulte de moins de 70 ans ?","a":"<ul><li><strong>Perte de poids ≥ 5% en 1 mois</strong> ou <strong>≥ 10% en 6 mois</strong> ou <strong>≥ 10% par rapport au poids habituel avant l'épisode aigu</strong>.</li><li><strong>IMC &lt; 18,5 kg/m²</strong>.</li><li><strong>Masse musculaire diminuée</strong> (évaluée par des méthodes validées telles que la mesure anthropométrique, la DEXA, ou l'impédancemétrie bioélectrique).</li></ul>"},{"i":"bc9f82805fa9","n":250,"o":"250-6","u":"Diagnostic positif","t":"Connaître les critères diagnostiques de la dénutrition chez l'adulte (< 70 ans)","q":"Actuellement, selon les dernières recommandations (HAS, 2019), quels sont les critères diagnostiques de la dénutrition chez l'adulte de moins de 70 ans ?","a":"<p>Le diagnostic de dénutrition est porté chez l'adulte de moins de 70 ans en présence d'au moins <strong>un critère phénotypique</strong> et d'au moins <strong>un critère étiologique</strong>.</p>"},{"i":"bec3feb0cb91","n":250,"o":"250-6","u":"Diagnostic positif","t":"Connaître les critères diagnostiques de la dénutrition chez l'adulte (< 70 ans)","q":"Quels sont les critères étiologiques à considérer pour le diagnostic de dénutrition chez l'adulte de moins de 70 ans ?","a":"<ul><li><strong>Apports alimentaires diminués</strong> ou <strong>absorption diminuée</strong> (apport énergétique &lt; 75% des besoins ou &lt; 1500 kcal/j pendant &gt; 1 semaine, ou toute situation d'absorption diminuée).</li><li><strong>Hypercatabolisme</strong> avéré (présence d'une pathologie aiguë ou chronique associée à une inflammation ou une augmentation des besoins métaboliques).</li></ul>"},{"i":"0355f8a20878","n":250,"o":"250-7","u":"Diagnostic positif","t":"Connaître les critères diagnostiques de la dénutrition chez la personne âgée (> 70 ans)","q":"Quelle est la définition d'une perte de poids significative dans le diagnostic de dénutrition chez la personne âgée de plus de 70 ans ?","a":"<p>Pour le diagnostic de dénutrition chez la personne âgée, une perte de poids est jugée significative si elle est :</p><ul><li><strong>&ge; 5%</strong> en <strong>6 mois</strong>.</li><li><strong>&ge; 10%</strong> en <strong>12 mois</strong>.</li></ul>"},{"i":"487bf6c1d6d0","n":250,"o":"250-7","u":"Diagnostic positif","t":"Connaître les critères diagnostiques de la dénutrition chez la personne âgée (> 70 ans)","q":"Quels sont les trois critères majeurs diagnostiques de la dénutrition chez la personne âgée de plus de 70 ans, selon la HAS ?","a":"<p>Les trois critères majeurs sont :</p><ul><li>Une <strong>perte de poids involontaire</strong> au cours des 6 derniers mois (≥ 5%) ou au cours des 12 derniers mois (≥ 10%).</li><li>Un <strong>IMC</strong> (Indice de Masse Corporelle) <strong>&lt; 21 kg/m²</strong>.</li><li>Une <strong>albuminémie &lt; 35 g/L</strong>.</li></ul>"},{"i":"616596c39640","n":250,"o":"250-7","u":"Diagnostic positif","t":"Connaître les critères diagnostiques de la dénutrition chez la personne âgée (> 70 ans)","q":"Comment interpréter la présence d'un ou plusieurs critères majeurs pour le diagnostic de dénutrition chez la personne âgée (&gt; 70 ans) ?","a":"<p>La présence d'<strong>un seul critère majeur</strong> (perte de poids, IMC &lt; 21, ou albuminémie &lt; 35 g/L) est suffisante pour poser le diagnostic de dénutrition chez la personne âgée.</p>"}]};